#include <iostream>
#include <string>
#include <stdexcept>
#include <exception>
#include <initializer_list>
using namespace std;

template <class T> class Queue {
    struct Node { T theItem; Node* next; };
    Node* head;
    Node* tail;
    int count;
public:
    Queue() : head(nullptr), tail(nullptr), count(0) {}
    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;
    ~Queue() { while (!isEmpty()) dequeue(); }
    bool isEmpty() const { return head == nullptr; }
    int size() const { return count; }
    void enqueue(T value) {
        Node* node = new Node{value, nullptr};
        if (isEmpty()) head = node; // First node becomes BOTH ends.
        else tail->next = node;
        tail = node;
        ++count;
    }
    T front() const {
        if (isEmpty()) throw runtime_error("Empty queue");
        return head->theItem;
    }
    T dequeue() {
        if (isEmpty()) throw runtime_error("Empty queue");
        Node* old = head;
        T value = old->theItem;
        head = head->next;
        if (head == nullptr) tail = nullptr; // Last node was removed.
        delete old;
        --count;
        return value;
    }
};

bool contains(Queue<int>& q, int target) {
    bool found = false;
    int n = q.size(); // Save the count: re-enqueueing keeps the queue nonempty.
    for (int i = 0; i < n; ++i) {
        int value = q.dequeue();
        if (value == target) found = true;
        q.enqueue(value);
    }
    return found;
}

