template <class T> class Queue {
    struct Node { T theItem; Node* next; };
    Node* head;
    Node* tail;
    int count;
public:
    Queue() : head(nullptr), tail(nullptr), count(0) {}
    Queue(const Queue&) = delete;
    Queue& operator=(const Queue&) = delete;
    ~Queue() { while (!isEmpty()) dequeue(); }
    bool isEmpty() const { return head == nullptr; }
    int size() const { return count; }
    void enqueue(T value) {
        Node* node = new Node{value, nullptr};
        if (isEmpty()) head = node; // First node becomes BOTH ends.
        else tail->next = node;
        tail = node;
        ++count;
    }
    T front() const {
        if (isEmpty()) throw runtime_error("Empty queue");
        return head->theItem;
    }
    T dequeue() {
        if (isEmpty()) throw runtime_error("Empty queue");
        Node* old = head;
        T value = old->theItem;
        head = head->next;
        if (head == nullptr) tail = nullptr; // Last node was removed.
        delete old;
        --count;
        return value;
    }
};

int clearQueue(Queue<int>& q) {
    int removed = 0;
    while (!q.isEmpty()) {
        q.dequeue(); // dequeue also updates head/tail and frees each node.
        ++removed;
    }
    return removed;
}

