        for (IntSLLNode* p = head; p != nullptr; p = p->next) cout << p->info << ' ';
        cout << '\n';
    }
    int size() const {
        int count = 0;
        for (IntSLLNode* p = head; p != nullptr; p = p->next) ++count;
        return count; // p moves; head stays unchanged.
    }
};

